def luck_dialog():
    return '''<dialog id="luck-dialog" class="luck-dialog" aria-labelledby="luck-title"><button type="button" class="luck-close" data-luck-close aria-label="关闭好运签" autofocus>×</button><p class="eyebrow">A LITTLE LUCK FOR YOUR RESEARCH</p><div class="luck-seal" aria-hidden="true">好运</div><h2 id="luck-title">你的努力，值得好消息。</h2><p class="luck-message" data-luck-message role="status" aria-live="polite">点一下，把今天的好运收下。</p><button type="button" class="button luck-claim" data-luck-claim>接住好运 <span>✦</span></button><p class="luck-saved" data-luck-saved></p><a href="fortune.html" class="text-link">看看投稿日历 →</a><p class="luck-footnote">科研人的小仪式 · 祝福不预测录用结果</p><div class="luck-confetti" aria-hidden="true"></div></dialog>'''

def ranking(articles):
    stats = json.loads((ROOT / 'data/article-stats.json').read_text())
    by_id = {a['id']: a for a in articles}
    metrics = [('reads', '阅读榜', '阅读'), ('likes', '点赞榜', '点赞'), ('shares', '转发榜', '转发'), ('watching', '在看榜', '在看')]
    tabs = ''.join(f'<button type="button" data-rank-tab="{key}" aria-pressed="{str(i == 0).lower()}" aria-controls="rank-{key}">{label}</button>' for i, (key, label, _) in enumerate(metrics))
    groups = []
    for key, label, unit in metrics:
        selected = sorted((r for r in stats['records'] if r[key] is not None), key=lambda r: (-r[key], -r['reads'], r['id']))[:10]
        rows = []
        for i, record in enumerate(selected, 1):
            a = by_id[record['id']]
            details = ''.join(f'<span>{name} <b>{record[field]:,}</b></span>' for field, _, name in metrics if field != key)
            rows.append(f'''<li class="rank-card" data-rank-id="{a['id']}" data-rank-value="{record[key]}"><div class="rank-number rank-number-{i}">{i:02d}</div><div class="rank-body"><div class="rank-meta"><span>{E(a['section'])}</span><time datetime="{a['date']}">{a['date'].replace('-', '.')}</time></div><h3><a href="{E(a['url'])}" title="{E(a['title'])}" target="_blank" rel="noopener noreferrer">{E(a['title'])}</a></h3><div class="rank-counts"><strong>{record[key]:,}<small>{unit}</small></strong><div>{details}</div></div><div class="rank-actions"><button type="button" data-bookmark="{a['id']}" class="rank-save" aria-pressed="false" title="收藏在当前浏览器，公众号收藏数未提供">☆<span>收藏</span></button><button type="button" data-share-url="{E(a['url'])}" data-share-title="{E(a['title'])}">↗ 转发</button><a href="{E(a['url'])}" target="_blank" rel="noopener noreferrer">阅读全文 ↗</a></div></div></li>''')
        groups.append(f'<section class="rank-group" id="rank-{key}" data-rank-group="{key}" aria-label="{label}前十"><h3 class="rank-group-title">{label} · TOP 10</h3><ol class="rank-grid">{"".join(rows)}</ol></section>')
    return f'''<section class="wrap section popularity-section" id="popular" aria-labelledby="popular-title"><div class="section-heading"><div><p class="eyebrow">COMMUNITY FAVORITES / TOP 10</p><h2 id="popular-title">公众号人气榜，先读这十篇。</h2><p>看看大家在读什么，把感兴趣的研究留给下一次阅读。</p></div><span class="rank-snapshot">公众号数据快照<br><strong>{stats['snapshotDate'].replace('-', '.')}</strong></span></div><div class="rank-toolbar"><div class="rank-tabs" role="group" aria-label="排行榜排序方式">{tabs}</div><a href="papers.html?saved=1">我的收藏 ☆</a></div>{''.join(groups)}<p class="ranking-note">榜单按 Excel 原始计数降序取前 10；同值按阅读数、文章编号排序。数据截至 {stats['snapshotDate']}，不是网站实时访问量。原表未提供收藏数；此处收藏仅保存在当前浏览器，转发不回写公众号统计。</p></section>'''

